// v0.4-split: Field value, control, chat, and emphasis render helpers
// Generated by responsibility split. No functional change intended.

function getFieldValue(row, field) {
  return getByPath(row, field.field);
}

function compareValues(a, b, field) {
  if (a == null || a === '') return (b == null || b === '') ? 0 : 1;
  if (b == null || b === '') return -1;
  if (field?.type === 'number') {
    const na = Number(a);
    const nb = Number(b);
    if (Number.isFinite(na) && Number.isFinite(nb)) return na - nb;
  }
  if (field?.type === 'boolean') return String(a).localeCompare(String(b));
  return String(a).localeCompare(String(b), 'ja', {numeric: true, sensitivity: 'base'});
}

function applySortToFilteredRows() {
  if (!sortState.field || !sortState.direction) return;
  const gd = gridDef();
  const field = gd.fields.find(f => f.field === sortState.field);
  if (!field) return;
  const dir = sortState.direction === 'asc' ? 1 : -1;
  filteredRows.sort((x, y) => {
    const c = compareValues(getFieldValue(x.row, field), getFieldValue(y.row, field), field);
    return c === 0 ? x.index - y.index : c * dir;
  });
}

function cycleSort(fieldName) {
  if (sortState.field !== fieldName) {
    sortState = {field: fieldName, direction: 'asc'};
  } else if (sortState.direction === 'asc') {
    sortState.direction = 'desc';
  } else {
    sortState = {field: null, direction: null};
  }
  applySortToFilteredRows();
  renderGrid();
}

function selectedDisplayPosition() {
  if (selectedIndex < 0) return '-';
  const pos = filteredRows.findIndex(x => x.index === selectedIndex);
  return pos >= 0 ? String(pos + 1) : '範囲外';
}

function mainView() { return viewDef.views?.[0] ?? viewDef; }
function headerDef() { return mainView().sections.find(s => s.type === 'form' && s.role !== 'detailOnly'); }
function gridDef() { return mainView().sections.find(s => s.type === 'grid'); }

function convertValue(type, value) {
  if (Array.isArray(value)) return value;
  if (type === 'number') return value === '' ? null : Number(value);
  if (type === 'boolean') return value === 'true' || value === true;
  if (type === 'array') {
    if (value == null || value === '') return [];
    return String(value).split(',').map(x => x.trim()).filter(Boolean);
  }
  return value;
}


function formatNumber(value, pattern) {
  if (value == null || value === '') return '';
  const n = Number(value);
  if (!Number.isFinite(n)) return String(value);
  if (!pattern) return String(value);
  const m = String(pattern).match(/\.([0#]+)/);
  if (!m) return String(value);
  return n.toFixed(m[1].length);
}


function formatArrayValueWithOptions(value, field=null) {
  const values = Array.isArray(value)
    ? value
    : (value == null || value === '' ? [] : String(value).split(',').map(x => x.trim()).filter(Boolean));
  if (!values.length) return '';
  if (!Array.isArray(field?.options) || !field.options.length) return values.join(' / ');
  return values.map(v => optionLabelForValue(v, field) ?? v).join(' / ');
}

function formatValue(value, field=null) {
  if (value == null) return '';
  if (typeof formatTargetContextValue === 'function') {
    const targetContextText = formatTargetContextValue(value, field);
    if (targetContextText != null) return targetContextText;
  }
  if (field?.type === 'select') return String(optionLabelForValue(value, field) ?? '');
  if (field?.type === 'number') return formatNumber(value, field.format ?? field.grid?.format ?? field.edit?.format);
  if ((field?.type === 'array' || field?.type === 'stringArray') && (Array.isArray(value) || Array.isArray(field?.options))) {
    return formatArrayValueWithOptions(value, field);
  }
  if (field?.type === 'objectArray' && Array.isArray(value)) return `${value.length}件`;
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value);
}


function wantsListBox(field) {
  return field?.edit?.control === 'listbox' || field?.edit?.selectMode === 'listbox' || field?.control === 'listbox';
}

function applySelectDisplayMode(input, field) {
  if (!wantsListBox(field)) return;
  const optionCount = (field.options?.length ?? 0) + 1;
  input.size = Math.max(2, optionCount);
  input.classList.add('listbox-select');
}


function wantsRadioControl(field) {
  return field?.edit?.control === 'radio' || field?.control === 'radio';
}

function createRadioControl(field, value, prefix, readonly=false) {
  const group = document.createElement('div');
  group.className = 'field-radio-group';
  const name = `${prefix}_${field.field}_${selectedIndex}`;
  (field.options ?? []).forEach(opt => {
    const optValue = optionValue(opt, field);
    const optLabel = optionLabel(opt, field);
    const label = document.createElement('label');
    label.className = 'field-radio-option';
    const input = document.createElement('input');
    input.type = 'radio';
    input.name = name;
    input.value = optValue;
    input.dataset.field = field.field;
    input.dataset.type = field.type ?? 'select';
    input.dataset.prefix = prefix;
    input.checked = String(value ?? field.defaultValue ?? '') === String(optValue);
    if (readonly) input.disabled = true;
    label.appendChild(input);
    const text = document.createElement('span');
    text.textContent = String(optLabel);
    label.appendChild(text);
    group.appendChild(label);
  });
  return group;
}

function stripReviewOptionLabel(value) {
  return String(value ?? '').replace(/^[◎△×★]\s*/, '');
}

function createEmbeddedChatField(config, row, gd, prefix) {
  const srcField = (gd?.fields ?? []).find(f => f.field === config.field) ?? {};
  const merged = { ...srcField, ...config, edit: { ...(srcField.edit ?? {}), ...(config.edit ?? {}) } };
  const readonly = Boolean(merged.readonly || merged.edit?.readonly);
  const current = getByPath(row, merged.field) ?? merged.defaultValue ?? '';

  const box = document.createElement('div');
  box.className = 'chat-embedded-field';

  if (config.label) {
    const cap = document.createElement('span');
    cap.className = 'chat-embedded-caption';
    cap.textContent = config.label;
    box.appendChild(cap);
  }

  const control = merged.control ?? merged.edit?.control;
  if (control === 'radio') {
    const group = document.createElement('div');
    group.className = 'chat-radio-group';
    const name = `${prefix}_${merged.field}_${selectedIndex}`;
    (merged.options ?? []).forEach(opt => {
      const optValue = optionValue(opt, merged);
      const optLabel = optionLabel(opt, merged);
      const label = document.createElement('label');
      label.className = 'chat-radio-option';

      const input = document.createElement('input');
      input.type = 'radio';
      input.name = name;
      input.value = optValue;
      input.dataset.field = merged.field;
      input.dataset.type = merged.type ?? 'select';
      input.dataset.prefix = prefix;
      input.checked = String(current) === String(optValue);
      if (readonly) input.disabled = true;

      label.appendChild(input);

      const text = document.createElement('span');
      text.textContent = stripReviewOptionLabel(optLabel);
      label.appendChild(text);

      group.appendChild(label);
    });
    box.appendChild(group);
    return box;
  }

  const normal = createInput(merged, current, prefix, readonly, row, gd);
  normal.classList.add('chat-embedded-normal');
  box.appendChild(normal);
  return box;
}

function normalizeChatMessages(field, row, gd) {
  const configured = field?.edit?.messages ?? field?.messages ?? field?.chat?.messages;
  if (Array.isArray(configured) && configured.length) return configured;

  // 既存のAI制約設計書v0.3形式を、専用データ移行なしでチャット表示できる既定マッピング。
  const existing = new Set((gd?.fields ?? []).map(f => f.field));
  const candidates = [
    { role: 'constraint', field: 'statement', label: '制約本文', readonly: true },
    { role: 'user', field: 'user_comment', label: '俺コメント' },
    { role: 'ai', field: 'ai_response', label: 'AI回答', readonly: true },
    { role: 'user', field: 'user_reply', label: '俺追加回答' },
    { role: 'ai', field: 'ai_followup_response', label: 'AI再回答', readonly: true }
  ];
  return candidates.filter(m => existing.has(m.field));
}

function currentDetailRow() {
  if (detailMode === 'new') return draftRow;
  if (selectedIndex >= 0 && Array.isArray(currentRows)) return currentRows[selectedIndex];
  return null;
}

function chatTextValue(row, fieldName) {
  return String(getByPath(row, fieldName) ?? '').trim();
}


function normalizeChatMarkdownConfig(...configs) {
  const result = { enabled: false, allowLinks: true, allowImages: false };
  configs.forEach(cfg => {
    if (cfg == null || cfg === false) return;
    if (cfg === true) {
      result.enabled = true;
      result.allowLinks = true;
      result.allowImages = true;
      return;
    }
    if (typeof cfg !== 'object') return;
    const inline = cfg.inline;
    const enabled = cfg.enabled ?? cfg.markdown ?? inline?.enabled;
    if (enabled === false) return;
    if (enabled === true || cfg.allowLinks != null || cfg.allowImages != null || inline === true || typeof inline === 'object') {
      result.enabled = true;
    }
    const linkValue = cfg.allowLinks ?? cfg.allow_links ?? inline?.allowLinks ?? inline?.allow_links;
    const imageValue = cfg.allowImages ?? cfg.allow_images ?? inline?.allowImages ?? inline?.allow_images;
    if (linkValue != null) result.allowLinks = Boolean(linkValue);
    if (imageValue != null) result.allowImages = Boolean(imageValue);
  });
  return result;
}

function escapeHtmlText(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function escapeHtmlAttr(value) {
  return escapeHtmlText(value).replace(/`/g, '&#96;');
}

function isSafeMarkdownUrl(url) {
  const text = String(url ?? '').trim();
  if (!text) return false;
  const compact = text.replace(/\s+/g, '').toLowerCase();
  if (compact.startsWith('javascript:') || compact.startsWith('vbscript:') || compact.startsWith('data:')) return false;
  return true;
}

function hasInlineMarkdownSyntax(text, cfg) {
  const value = String(text ?? '');
  if (!cfg?.enabled || !value) return false;
  if (cfg.allowImages && /!\[[^\]]*\]\([^\)]+\)/.test(value)) return true;
  if (cfg.allowLinks && /(^|[^!])\[[^\]]+\]\([^\)]+\)/.test(value)) return true;
  return false;
}

function renderInlineMarkdown(text, cfg) {
  let html = escapeHtmlText(text);
  if (!cfg?.enabled) return html;

  if (cfg.allowImages) {
    html = html.replace(/!\[([^\]]*)\]\(([^\s\)]+)(?:\s+&quot;([^&]*)&quot;)?\)/g, (m, alt, url, title) => {
      const cleanUrl = String(url ?? '').trim();
      if (!isSafeMarkdownUrl(cleanUrl)) return m;
      const titleAttr = title ? ` title="${escapeHtmlAttr(title)}"` : '';
      return `<img class="chat-md-image" src="${escapeHtmlAttr(cleanUrl)}" alt="${escapeHtmlAttr(alt)}" loading="lazy"${titleAttr}>`;
    });
  }

  if (cfg.allowLinks) {
    html = html.replace(/(^|[^!])\[([^\]]+)\]\(([^\s\)]+)(?:\s+&quot;([^&]*)&quot;)?\)/g, (m, prefix, label, url, title) => {
      const cleanUrl = String(url ?? '').trim();
      if (!isSafeMarkdownUrl(cleanUrl)) return m;
      const titleAttr = title ? ` title="${escapeHtmlAttr(title)}"` : '';
      return `${prefix}<a class="chat-md-link" href="${escapeHtmlAttr(cleanUrl)}" target="_blank" rel="noopener noreferrer"${titleAttr}>${label}</a>`;
    });
  }

  return html;
}


function renderInlineMarkdownTokens(text, cfg) {
  let html = escapeHtmlText(text);
  if (!cfg?.enabled) return html;

  // inline code first, then emphasis, then links/images.
  html = html.replace(/`([^`]+)`/g, '<code class="md-inline-code">$1</code>');
  html = html.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  html = html.replace(/__([^_]+)__/g, '<strong>$1</strong>');
  html = html.replace(/(^|[^*])\*([^*\n]+)\*/g, '$1<em>$2</em>');

  if (cfg.allowImages) {
    html = html.replace(/!\[([^\]]*)\]\(([^\s\)]+)(?:\s+&quot;([^&]*)&quot;)?\)/g, (m, alt, url, title) => {
      const cleanUrl = String(url ?? '').trim();
      if (!isSafeMarkdownUrl(cleanUrl)) return m;
      const titleAttr = title ? ` title="${escapeHtmlAttr(title)}"` : '';
      return `<img class="chat-md-image" src="${escapeHtmlAttr(cleanUrl)}" alt="${escapeHtmlAttr(alt)}" loading="lazy"${titleAttr}>`;
    });
  }

  if (cfg.allowLinks) {
    html = html.replace(/(^|[^!])\[([^\]]+)\]\(([^\s\)]+)(?:\s+&quot;([^&]*)&quot;)?\)/g, (m, prefix, label, url, title) => {
      const cleanUrl = String(url ?? '').trim();
      if (!isSafeMarkdownUrl(cleanUrl)) return m;
      const titleAttr = title ? ` title="${escapeHtmlAttr(title)}"` : '';
      return `${prefix}<a class="chat-md-link" href="${escapeHtmlAttr(cleanUrl)}" target="_blank" rel="noopener noreferrer"${titleAttr}>${label}</a>`;
    });
  }

  return html;
}

function renderMarkdownContent(text, cfg) {
  const raw = String(text ?? '').replace(/\r\n/g, '\n');
  if (!cfg?.enabled) return escapeHtmlText(raw);
  if (!raw) return '';

  const lines = raw.split('\n');
  const out = [];
  let paragraph = [];
  let listType = null;
  let listItems = [];
  let inCode = false;
  let codeLines = [];

  const flushParagraph = () => {
    if (!paragraph.length) return;
    out.push(`<p>${paragraph.join('<br>')}</p>`);
    paragraph = [];
  };
  const flushList = () => {
    if (!listType || !listItems.length) return;
    out.push(`<${listType}>${listItems.map(x => `<li>${x}</li>`).join('')}</${listType}>`);
    listType = null;
    listItems = [];
  };
  const flushCode = () => {
    out.push(`<pre><code>${escapeHtmlText(codeLines.join('\n'))}</code></pre>`);
    codeLines = [];
  };

  lines.forEach(line => {
    const trimmed = line.trim();

    if (/^```/.test(trimmed)) {
      if (inCode) {
        flushCode();
        inCode = false;
      } else {
        flushParagraph();
        flushList();
        inCode = true;
        codeLines = [];
      }
      return;
    }

    if (inCode) {
      codeLines.push(line);
      return;
    }

    if (!trimmed) {
      flushParagraph();
      flushList();
      return;
    }

    const heading = line.match(/^\s*(#{1,6})\s+(.+)$/);
    if (heading) {
      flushParagraph();
      flushList();
      const level = Math.min(heading[1].length, 6);
      out.push(`<h${level}>${renderInlineMarkdownTokens(heading[2].trim(), cfg)}</h${level}>`);
      return;
    }

    const unordered = line.match(/^\s*[-*+]\s+(.+)$/);
    if (unordered) {
      flushParagraph();
      if (listType && listType !== 'ul') flushList();
      listType = 'ul';
      listItems.push(renderInlineMarkdownTokens(unordered[1], cfg));
      return;
    }

    const ordered = line.match(/^\s*\d+[.)]\s+(.+)$/);
    if (ordered) {
      flushParagraph();
      if (listType && listType !== 'ol') flushList();
      listType = 'ol';
      listItems.push(renderInlineMarkdownTokens(ordered[1], cfg));
      return;
    }

    const quote = line.match(/^\s*>\s?(.*)$/);
    if (quote) {
      flushParagraph();
      flushList();
      out.push(`<blockquote>${renderInlineMarkdownTokens(quote[1], cfg)}</blockquote>`);
      return;
    }

    flushList();
    paragraph.push(renderInlineMarkdownTokens(line, cfg));
  });

  if (inCode) flushCode();
  flushParagraph();
  flushList();

  return out.join('\n');
}

function chatMessageMarkdownConfig(field, msg, srcField) {
  return normalizeChatMarkdownConfig(
    field?.markdown,
    field?.edit?.markdown,
    field?.chat?.markdown,
    srcField?.markdown,
    srcField?.edit?.markdown,
    msg?.markdown
  );
}

function shouldRenderChatMessage(msg, row, inputCfg=null) {
  const fieldName = msg?.field;
  if (!fieldName) return true;

  // v0.7-chat-input-mapping:
  // 送信欄の保存先 userField は、messages定義位置ではなく末尾表示へ寄せる。
  // これにより「最後のAI回答の直前に新コメントが割り込む」時系列崩れを防ぐ。
  if (inputCfg?.appendPosition === 'afterMessages' && fieldName === inputCfg.userField) {
    return false;
  }

  // 追加会話は、まだ人間が追記していない間は空の吹き出しを出さない。
  if (fieldName === 'user_reply') {
    return chatTextValue(row, 'user_reply') !== '';
  }

  // AI再回答は、人間の追記が入った時点で「空のAI回答待ち欄」として表示する。
  if (fieldName === 'ai_followup_response') {
    return chatTextValue(row, 'user_reply') !== '' || chatTextValue(row, 'ai_followup_response') !== '';
  }

  return true;
}

function chatInputConfig(field, gd) {
  const raw = field?.edit?.input ?? field?.input ?? field?.chat?.input;
  const cfg = raw ?? {};
  const existing = new Set((gd?.fields ?? []).map(f => f.field));
  const hasExplicitInput = raw && typeof raw === 'object';
  const userField = cfg.userField ?? cfg.user_field ?? (!hasExplicitInput && existing.has('user_reply') ? 'user_reply' : null);
  const aiField = cfg.aiField ?? cfg.ai_field ?? (!hasExplicitInput && existing.has('ai_followup_response') ? 'ai_followup_response' : null);
  const appendPosition = cfg.appendPosition ?? cfg.append_position ?? 'afterMessages';
  return {
    enabled: cfg.enabled !== false && Boolean(userField),
    userField,
    aiField,
    appendPosition,
    placeholder: cfg.placeholder ?? 'この行へのコメントを追加...',
    sendLabel: (cfg.sendLabel ?? cfg.send_label ?? '送信') || '送信',
    label: cfg.label ?? cfg.appendLabel ?? cfg.append_label ?? null,
    markdown: normalizeChatMarkdownConfig(field?.markdown, field?.edit?.markdown, field?.chat?.markdown, cfg.markdown)
  };
}

function createChatComposer(field, row, gd, prefix) {
  const cfg = chatInputConfig(field, gd);
  if (!cfg.enabled) return null;

  const composer = document.createElement('div');
  composer.className = 'chat-composer';

  const plus = document.createElement('div');
  plus.className = 'chat-composer-plus';
  plus.textContent = '+';
  composer.appendChild(plus);

  const input = document.createElement('textarea');
  input.className = 'chat-composer-input';
  input.placeholder = cfg.placeholder;
  input.rows = 1;
  input.dataset.prefix = prefix;
  composer.appendChild(input);

  const send = document.createElement('button');
  send.type = 'button';
  send.className = 'chat-composer-send';
  send.textContent = cfg.sendLabel;
  composer.appendChild(send);

  const submit = () => {
    const text = input.value.trim();
    if (!text) {
      input.focus();
      return;
    }

    const targetRow = currentDetailRow() ?? row;
    if (!targetRow) return;

    // 送信前に画面上の未反映入力を行データへ回収する。
    applyDetailInputsToRow(targetRow);

    const previous = chatTextValue(targetRow, cfg.userField);
    const next = previous ? `${previous}\n\n${text}` : text;
    setByPath(targetRow, cfg.userField, next);

    if (cfg.aiField && getByPath(targetRow, cfg.aiField) == null) {
      setByPath(targetRow, cfg.aiField, '');
    }

    renderDetailForRow(targetRow);
    setStatus('コメントを追加しました。必要に応じてAI再回答欄へ回答を追記してください。');
  };

  send.addEventListener('click', submit);
  input.addEventListener('input', () => {
    input.style.height = 'auto';
    input.style.height = Math.min(input.scrollHeight, 120) + 'px';
  });
  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
      e.preventDefault();
      submit();
    }
  });

  return composer;
}


function markdownPreviewRawValue(el) {
  // contenteditable の innerText は最後に余分な改行が付くことがあるので、
  // 元データと近い形へ軽く正規化する。
  return String(el?.innerText ?? '').replace(/\u00a0/g, ' ').replace(/\n+$/g, '');
}

function syncMarkdownRawToRow(el, rawValue) {
  const fieldName = el?.dataset?.field;
  if (!fieldName) return;
  const row = currentDetailRow();
  if (!row) return;
  const gd = gridDef();
  const field = (gd?.fields ?? []).find(f => f.field === fieldName);
  const type = field?.type ?? el.dataset.type ?? 'textarea';
  setByPath(row, fieldName, convertValue(type, rawValue));
}

function restoreMarkdownPreviewElement(el, mdCfg, rawValue, options={}) {
  if (!el || !mdCfg?.enabled) return;
  el.dataset.rawValue = rawValue;
  el.dataset.markdownDisplay = 'true';
  el.dataset.editMode = 'preview';
  el.contentEditable = 'false';
  el.innerHTML = renderMarkdownContent(rawValue, mdCfg);
  el.classList.add('markdown-rendered');
  el.classList.remove('markdown-raw-editing', 'chat-md-editing');
  if (options.displayClass) el.classList.add(options.displayClass);
  if (options.item && options.itemDisplayClass) options.item.classList.add(options.itemDisplayClass);
  if (options.displayOnly) {
    el.classList.add('chat-display-only');
    if (options.item) options.item.classList.add('chat-display-only');
  }
}

function installMarkdownBlurPreview(el, mdCfg, options={}) {
  if (!el || !mdCfg?.enabled) return;
  el.addEventListener('blur', () => {
    if (el.dataset.editMode !== 'raw') return;
    const rawValue = markdownPreviewRawValue(el);
    syncMarkdownRawToRow(el, rawValue);
    restoreMarkdownPreviewElement(el, mdCfg, rawValue, options);
    if (typeof setStatus === 'function') {
      setStatus('Markdownプレビューを更新しました（保存する場合は上書き保存してください）');
    }
  });
}

function createChatMessageElement(field, msg, row, gd, prefix, options={}) {
  const srcField = (gd?.fields ?? []).find(f => f.field === msg.field) ?? {};
  const raw = getByPath(row, msg.field);
  const rawText = raw == null ? '' : String(raw);
  const role = String(msg.role ?? '').toLowerCase();
  const isAi = role === 'ai' || role === 'assistant';
  const isUser = role === 'user' || role === 'human' || role === '俺';
  const isConstraint = role === 'constraint' || role === 'system' || role === 'statement';
  const renderMarkdownOnly = Boolean(
    options.renderMarkdownOnly ??
    options.markdownDisplay ??
    options.displayMode === 'markdown'
  );
  const mdCfg = normalizeChatMarkdownConfig(chatMessageMarkdownConfig(field, msg, srcField), options.markdown);
  const baseReadonly = Boolean(options.readonly ?? msg.readonly ?? srcField.readonly ?? srcField.edit?.readonly);
  // v0.10-markdown-preview-display-mode:
  // ViewDefでMarkdown許可されたchat messageは、通常表示ではMarkdownプレビュー、
  // クリック後だけMarkdown原文編集へ切り替える。
  const editableMarkdownDisplay = Boolean(options.editableMarkdownDisplay ?? (mdCfg.enabled && !baseReadonly && !renderMarkdownOnly));
  const readonly = baseReadonly || (renderMarkdownOnly && !editableMarkdownDisplay);

  const item = document.createElement('div');
  item.className = 'chat-message ' + (isAi ? 'chat-ai' : isUser ? 'chat-user' : isConstraint ? 'chat-constraint' : 'chat-other');

  const meta = document.createElement('div');
  meta.className = 'chat-meta';
  meta.textContent = msg.label ?? srcField.caption ?? msg.field;
  item.appendChild(meta);

  const embeddedFields = msg.embeddedFields ?? msg.embedded_fields ?? [];
  if (Array.isArray(embeddedFields) && embeddedFields.length) {
    const embeddedWrap = document.createElement('div');
    embeddedWrap.className = 'chat-embedded-fields';
    embeddedFields.forEach(ef => embeddedWrap.appendChild(createEmbeddedChatField(ef, row, gd, prefix)));
    item.appendChild(embeddedWrap);
  }

  const bubble = document.createElement('div');
  bubble.className = 'chat-text';
  bubble.dataset.field = msg.field;
  bubble.dataset.type = srcField.type ?? 'textarea';
  bubble.dataset.prefix = prefix;
  bubble.dataset.placeholder = msg.placeholder ?? '';
  bubble.setAttribute('role', 'textbox');
  bubble.setAttribute('aria-label', msg.label ?? srcField.caption ?? msg.field);
  bubble.setAttribute('spellcheck', 'false');
  // editableMarkdownDisplay の場合、通常時はHTML表示を守るため contenteditable=false。
  // クリックでMarkdown原文編集モードへ切り替える。
  bubble.contentEditable = (readonly || editableMarkdownDisplay) ? 'false' : 'true';

  // v0.8.1-chat-markdown-preview-fix / v0.9.1-chat-markdown-editable-fix:
  // 保存済みメッセージは「本文 + Markdown preview」の二重表示にしない。
  // appendPosition=afterMessages の送信済みユーザーコメントは、通常表示ではMarkdownを1回だけ描画し、
  // 編集時だけMarkdown原文へ戻す。
  if ((readonly || renderMarkdownOnly || editableMarkdownDisplay) && mdCfg.enabled) {
    bubble.innerHTML = renderMarkdownContent(rawText, mdCfg);
    bubble.dataset.rawValue = rawText;
    bubble.dataset.markdownDisplay = 'true';
    bubble.classList.add('markdown-rendered');
  } else {
    bubble.textContent = rawText;
  }

  if (renderMarkdownOnly) {
    bubble.classList.add('chat-display-only');
    item.classList.add('chat-display-only');
  }

  if (readonly) {
    bubble.classList.add('readonly');
    item.classList.add('readonly');
  }

  if (editableMarkdownDisplay && !readonly) {
    bubble.title = 'クリックするとMarkdown原文を編集できます';
    bubble.classList.add('chat-editable-markdown-display');
    item.classList.add('chat-editable-markdown-display');

    const enterMarkdownRawEditMode = () => {
      if (bubble.dataset.editMode === 'raw') return;
      const rawValue = bubble.dataset.rawValue ?? rawText;
      bubble.dataset.editMode = 'raw';
      bubble.classList.remove('markdown-rendered');
      bubble.classList.remove('chat-display-only');
      item.classList.remove('chat-display-only');
      bubble.classList.add('chat-md-editing');
      bubble.contentEditable = 'true';
      bubble.textContent = rawValue;
      requestAnimationFrame(() => {
        bubble.focus();
        const range = document.createRange();
        range.selectNodeContents(bubble);
        range.collapse(false);
        const sel = window.getSelection();
        if (sel) {
          sel.removeAllRanges();
          sel.addRange(range);
        }
      });
    };

    bubble.addEventListener('click', (e) => {
      // リンクは Ctrl/Cmdクリックなら通常リンクとして扱う。通常クリックは編集を優先。
      if (e.target.closest?.('a') && (e.ctrlKey || e.metaKey)) return;
      e.preventDefault();
      enterMarkdownRawEditMode();
    });

    installMarkdownBlurPreview(bubble, mdCfg, {
      item,
      displayClass: 'chat-editable-markdown-display',
      itemDisplayClass: 'chat-editable-markdown-display',
      displayOnly: renderMarkdownOnly
    });
  }

  bubble.addEventListener('keydown', (e) => {
    // contenteditable内ではF12/F7/F8だけ親の詳細操作へ渡す。
    if (e.key === 'F7' || e.key === 'F8' || e.key === 'F12') return;
    // Ctrl+Enter は反映のショートカット。改行は Enter で通常通り入力できる。
    if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
      e.preventDefault();
      applyDetail(e);
    }
  });
  item.appendChild(bubble);

  // Markdown previewは入力中/編集中の専用UIとして扱う。
  // 保存済みchat messageでは、原文とpreviewの二重表示を避けるため既定では出さない。
  if (!readonly && options.showMarkdownPreview === true && hasInlineMarkdownSyntax(rawText, mdCfg)) {
    const preview = document.createElement('div');
    preview.className = 'chat-markdown-preview';
    preview.innerHTML = renderMarkdownContent(rawText, mdCfg);
    item.appendChild(preview);
  }

  return item;
}

function findConfiguredChatMessage(messages, fieldName) {
  return (messages ?? []).find(m => m?.field === fieldName) ?? null;
}

function shouldAppendInputUserMessage(inputCfg, row) {
  return inputCfg?.enabled && inputCfg.appendPosition === 'afterMessages' && inputCfg.userField && chatTextValue(row, inputCfg.userField) !== '';
}

function createChatInput(field, row, gd, prefix) {
  const wrap = document.createElement('div');
  wrap.className = 'field chat-field';

  const label = document.createElement('label');
  label.textContent = field.caption ?? '会話';
  wrap.appendChild(label);

  const timeline = document.createElement('div');
  timeline.className = 'chat-timeline';

  const inputCfg = chatInputConfig(field, gd);
  const messages = normalizeChatMessages(field, row, gd);
  messages.forEach(msg => {
    if (!shouldRenderChatMessage(msg, row, inputCfg)) return;
    timeline.appendChild(createChatMessageElement(field, msg, row, gd, prefix));
  });

  // v0.7-chat-input-mapping:
  // 送信欄由来の人間コメントは、messages定義位置に割り込ませず、会話の末尾に表示する。
  if (shouldAppendInputUserMessage(inputCfg, row)) {
    const original = findConfiguredChatMessage(messages, inputCfg.userField) ?? {};
    const msg = {
      ...original,
      role: original.role ?? 'user',
      field: inputCfg.userField,
      label: inputCfg.label ?? original.label ?? '追加コメント',
      markdown: inputCfg.markdown
    };
    timeline.appendChild(createChatMessageElement(field, msg, row, gd, prefix, {
      markdown: inputCfg.markdown,
      renderMarkdownOnly: true,
      editableMarkdownDisplay: true
    }));
  }

  const composer = createChatComposer(field, row, gd, prefix);
  if (composer) timeline.appendChild(composer);

  wrap.appendChild(timeline);
  return wrap;
}

function createSelectControlElement({ field, value }) {
  const input = document.createElement('select');
  const blank = document.createElement('option');
  blank.value = '';
  blank.textContent = '';
  input.appendChild(blank);
  (field.options ?? []).forEach(opt => {
    const o = document.createElement('option');
    o.value = optionValue(opt, field);
    o.textContent = optionLabel(opt, field);
    input.appendChild(o);
  });
  applySelectDisplayMode(input, field);
  setSelectValuePreservingUnknown(input, field, value);
  return input;
}

function fieldMarkdownConfig(field) {
  return normalizeChatMarkdownConfig(field?.markdown, field?.edit?.markdown, field?.display?.markdown);
}

function createMarkdownTextareaDisplayElement({ field, value, readonly }) {
  const mdCfg = fieldMarkdownConfig(field);
  const rawText = formatValue(value, field);
  const box = document.createElement('div');
  box.className = 'markdown-textarea-display markdown-rendered';
  box.setAttribute('role', 'textbox');
  box.setAttribute('aria-label', field.caption ?? field.field);
  box.setAttribute('spellcheck', 'false');
  box.dataset.rawValue = rawText;
  box.dataset.markdownDisplay = 'true';
  box.dataset.placeholder = field.placeholder ?? field.edit?.placeholder ?? '';
  box.contentEditable = 'false';
  box.innerHTML = renderMarkdownContent(rawText, mdCfg);
  if (field.edit?.height) box.style.minHeight = field.edit.height + 'px';

  if (readonly) {
    box.classList.add('readonly');
    return box;
  }

  box.title = 'クリックするとMarkdown原文を編集できます';
  box.classList.add('markdown-editable-display');

  const enterRawEditMode = () => {
    if (box.dataset.editMode === 'raw') return;
    const rawValue = box.dataset.rawValue ?? rawText;
    box.dataset.editMode = 'raw';
    box.classList.remove('markdown-rendered');
    box.classList.add('markdown-raw-editing');
    box.contentEditable = 'true';
    box.textContent = rawValue;
    requestAnimationFrame(() => {
      box.focus();
      const range = document.createRange();
      range.selectNodeContents(box);
      range.collapse(false);
      const sel = window.getSelection();
      if (sel) {
        sel.removeAllRanges();
        sel.addRange(range);
      }
    });
  };

  box.addEventListener('click', (e) => {
    if (e.target.closest?.('a') && (e.ctrlKey || e.metaKey)) return;
    e.preventDefault();
    enterRawEditMode();
  });

  installMarkdownBlurPreview(box, mdCfg, {
    displayClass: 'markdown-editable-display'
  });

  box.addEventListener('keydown', (e) => {
    if (e.key === 'F7' || e.key === 'F8' || e.key === 'F12') return;
    if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
      e.preventDefault();
      applyDetail(e);
    }
  });

  return box;
}

function createTextareaControlElement({ field, value, prefix, readonly }) {
  const mdCfg = fieldMarkdownConfig(field);
  // v0.10-markdown-preview-display-mode:
  // 詳細表示では、ViewDefでMarkdownを許可したtextareaをプレビュー表示する。
  // 保存値はMarkdown原文のまま保持し、クリック時だけ原文編集に切り替える。
  // 検索・ヘッダーでは従来どおり通常textareaを使う。
  if (prefix === 'detail' && mdCfg.enabled) {
    return createMarkdownTextareaDisplayElement({ field, value, readonly });
  }

  const input = document.createElement('textarea');
  input.value = formatValue(value, field);
  if (field.edit?.height) input.style.minHeight = field.edit.height + 'px';
  return input;
}

function createBooleanControlElement({ field, value }) {
  const input = document.createElement('select');
  ['', 'true', 'false'].forEach(v => {
    const o = document.createElement('option');
    o.value = v;
    o.textContent = v;
    input.appendChild(o);
  });
  applySelectDisplayMode(input, field);
  input.value = value === true ? 'true' : value === false ? 'false' : '';
  return input;
}

function createTextLikeControlElement({ field, value }) {
  const input = document.createElement('input');
  input.type = field.type === 'number' ? 'number' : field.type === 'datetime' ? 'text' : 'text';
  if (field.type === 'number') {
    const step = field.edit?.step ?? field.step;
    const min = field.edit?.min ?? field.min;
    const max = field.edit?.max ?? field.max;
    if (step != null) input.step = String(step);
    if (min != null) input.min = String(min);
    if (max != null) input.max = String(max);
  }
  input.value = typeof value === 'object' && value !== null ? formatValue(value, field) : (value ?? '');
  return input;
}

function createRadioControlElement({ field, value, prefix, readonly }) {
  return createRadioControl(field, value, prefix, readonly);
}

// v0.5-registry: field control factories.
registerFieldControl('radio', createRadioControlElement);
registerFieldControl('select', createSelectControlElement);
registerFieldControl('textarea', createTextareaControlElement);
registerFieldControl('boolean', createBooleanControlElement);
registerFieldControl('text', createTextLikeControlElement, [
  'number',
  'datetime',
  'objectArray',
  'stringArray'
]);

function isChildArrayField(field) {
  return field?.type === 'objectArray' || field?.type === 'stringArray';
}

function createInput(field, value, prefix, readonlyOverride=false, row=null, gd=null) {
  if (field.type === 'chat') return createChatInput(field, row ?? {}, gd ?? gridDef(), prefix);

  const readonly = readonlyOverride || field.readonly || field.edit?.readonly;
  const wrap = document.createElement('div');
  wrap.className = 'field' + (readonly ? ' readonly' : '');
  const label = document.createElement('label');
  const shortcut = field.edit?.shortcut ? ` (${field.edit.shortcut})` : '';
  label.textContent = (field.caption ?? field.field) + shortcut;
  wrap.appendChild(label);

  const input = createFieldControlElement({ field, value, prefix, readonly, row, gd });
  input.dataset.field = field.field;
  input.dataset.type = field.type ?? 'text';
  input.dataset.prefix = prefix;
  if (readonly) input.disabled = true;
  wrap.appendChild(input);
  return wrap;
}

function renderHeader() {
  const def = headerDef();
  if (!def) return;
  $('headerCaption').textContent = def.caption ?? 'Header';
  const form = $('headerForm');
  form.innerHTML = '';
  def.fields.forEach(field => {
    form.appendChild(createInput(field, getByPath(sourceData, (def.dataPath === '$' ? '$.' : def.dataPath + '.') + field.field), 'header'));
  });
  $('headerSection').classList.remove('hidden');
  // v0.15.5.2: Main Context is Data-side information. Show it as a header panel,
  // not as the main Grid. The ViewDef only declares data_path/display contract.
  if (typeof renderMainContextHeaderPanel === 'function') renderMainContextHeaderPanel($('headerSection'));
}

function renderSearch() {
  const gd = gridDef();
  const form = $('searchForm');
  form.innerHTML = '';
  gd.fields.filter(f => f.search?.visible).forEach(field => {
    const searchField = {...field, readonly:false, edit:{readonly:false}};
    if (field.type === 'number') {
      form.appendChild(createInput({...searchField, caption:(field.caption ?? field.field) + ' >='}, '', 'search'));
    } else {
      form.appendChild(createInput(searchField, '', 'search'));
    }
  });

  // v0.17.6-pluginhost-mvp: Plugin SearchFilterは通常検索欄の後ろに追加する。
  if (typeof renderStudioPluginSearchFilters === 'function') {
    renderStudioPluginSearchFilters(form, { gd, viewDef, sourceData, currentRows });
  }

  $('searchSection').classList.remove('hidden');
}


function detailPlacement(field) {
  return String(
    field?.layout?.placement ??
    field?.edit?.layout?.placement ??
    field?.edit?.placement ??
    field?.placement ??
    ''
  ).trim();
}

function detailAfter(field) {
  return String(
    field?.layout?.after ??
    field?.edit?.layout?.after ??
    field?.edit?.after ??
    field?.after ??
    ''
  ).trim();
}

function isDetailFooterField(field) {
  const placement = detailPlacement(field);
  const after = detailAfter(field);
  return placement === 'detailFooter' || placement === 'afterChildGrids' || after === 'childGrids';
}

function detailVisibleFields(gd) {
  // v0.7-objectarray-save-integrity:
  // objectArray / stringArray は childArea の専用サブグリッドで表示する。
  // Detail Form へ「2 items」のような表示専用テキスト入力を出すと、
  // 反映・保存時に配列本体を文字列へ壊す危険があるため除外する。
  return (gd?.fields ?? []).filter(f => f.edit?.visible !== false && !isChildArrayField(f));
}

function renderDetailFooterFields(row, gd) {
  const footerFields = detailVisibleFields(gd).filter(isDetailFooterField);
  if (!footerFields.length) return;

  const area = $('childArea');
  const wrap = document.createElement('div');
  wrap.className = 'detail-after-child-fields';

  footerFields.forEach(field => {
    wrap.appendChild(createInput(field, getByPath(row, field.field), 'detail', false, row, gd));
  });

  area.appendChild(wrap);
}



function valueIsFail(value) {
  return value === false || String(value).toLowerCase() === 'false' || String(value).toLowerCase() === 'fail';
}

function valueIsPass(value) {
  return value === true || String(value).toLowerCase() === 'true' || String(value).toLowerCase() === 'pass';
}

function hasMissingItems(value) {
  if (Array.isArray(value)) return value.length > 0;
  const text = String(value ?? '').trim();
  return text !== '' && text !== '[]' && text.toLowerCase() !== 'n/a';
}

function safeCssToken(value) {
  return String(value ?? '')
    .replace(/[^a-zA-Z0-9_-]/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
    .toLowerCase();
}

function applyGridRowEmphasis(tr, row) {
  const passValue = row?.pass;
  const statusValue = row?.status;
  const resultLabel = String(row?.resultLabel ?? '');

  if (valueIsFail(passValue) || valueIsFail(statusValue) || resultLabel.includes('FAIL') || resultLabel.includes('失敗')) {
    tr.classList.add('row-fail');
  } else if (valueIsPass(passValue) || valueIsPass(statusValue) || resultLabel.includes('PASS')) {
    tr.classList.add('row-pass');
  }

  if (hasMissingItems(row?.missing)) tr.classList.add('row-missing');
}

function applyGridCellEmphasis(td, field, row, value) {
  const fieldName = field?.field ?? '';
  const token = safeCssToken(fieldName);
  if (token) td.classList.add('cell-field-' + token);

  if (fieldName === 'pass' || fieldName === 'status') {
    if (valueIsFail(value)) td.classList.add('cell-fail', 'cell-result');
    if (valueIsPass(value)) td.classList.add('cell-pass', 'cell-result');
  }

  if (fieldName === 'missing') {
    td.classList.add('cell-missing-list');
    if (hasMissingItems(value)) td.classList.add('cell-missing');
    else td.classList.add('cell-missing-empty');
  }

  if (row?.pass === false || String(row?.pass).toLowerCase() === 'false') {
    if (fieldName === 'expected') td.classList.add('cell-expected-fail');
    if (fieldName === 'actual') td.classList.add('cell-actual-fail');
    if (fieldName === 'name') td.classList.add('cell-check-fail');
  }
}

// v0.5-registry: high-level renderer registrations.
registerRenderer('header', renderHeader);
registerRenderer('search', renderSearch);
registerRenderer('detailFooterFields', renderDetailFooterFields);

